+    const themeLabel = document.querySelector("#theme-label");
+    const savedTheme = localStorage.getItem("upb-theme");
+    const initialTheme = savedTheme === "black" ? "black" : "night";
+
+    function setTheme(theme) {
+      document.documentElement.dataset.theme = theme;
+      const isBlack = theme === "black";
+      themeLabel.textContent = isBlack ? "Black mode" : "Night mode";
+      themeButton.setAttribute("aria-label", `Switch to ${isBlack ? "night" : "black"} theme`);
+      themeButton.setAttribute("aria-pressed", String(isBlack));
+      localStorage.setItem("upb-theme", theme);
+    }
+
+    setTheme(initialTheme);
+    themeButton.addEventListener("click", () => {
+      setTheme(document.documentElement.dataset.theme === "night" ? "black" : "night");
+    });
+  </script>
+</body>
